_PHRASES = None


def T(s):
    if LANG != 'en' or not isinstance(s, str) or not s:
        return s
    if s in EN:
        return EN[s]
    global _PHRASES
    if _PHRASES is None:
        items = sorted(EN.items(), key=lambda kv: -len(kv[0]))
        _PHRASES = []
        for sk, en in items:
            if len(sk.strip()) < 3:
                continue
            pat = re.escape(sk)
            if sk[0].isalnum(): pat = r'(?<!\w)' + pat
            if sk[-1].isalnum(): pat = pat + r'(?!\w)'
            _PHRASES.append((re.compile(pat), en))
    for rx, en in _PHRASES:
        if rx.search(s):
            s = rx.sub(lambda m, en=en: en, s)
    return s
